    [RelayCommand]
    private async Task RandomizeDataAsync()
    {
        var cpu = _random.Next(25, 95);
        var ram = _random.Next(40, 92);
        var net = _random.NextDouble() * 3.5 + 0.5;

        CpuUsage = $"{cpu}%";
        CpuBarWidth = 150.0 * (cpu / 100.0);

        MemoryUsage = $"{ram}%";
        MemoryBarWidth = 150.0 * (ram / 100.0);

        NetworkSpeed = $"{net:F1} Gbps";
        NetworkBarWidth = Math.Min(150.0, 150.0 * (net / 5.0));

        for (int i = 0; i < _baseHeights.Length; i++)
        {
            _baseHeights[i] = _random.Next(60, 240);
        }

        UpdateChartStatus();
        await Task.CompletedTask;
    }

