        BarBrush1 = Brush.Parse(theme.Colors[0]);
        BarBrush2 = Brush.Parse(theme.Colors[1]);
        BarBrush3 = Brush.Parse(theme.Colors[2]);
        BarBrush4 = Brush.Parse(theme.Colors[3]);
        BarBrush5 = Brush.Parse(theme.Colors[4]);
        BarBrush6 = Brush.Parse(theme.Colors[5]);

